// Generated by `just generate` from `src/plugins/claudetto/slices/minispec/adapters/run.ts`. Edit the source and run `just generate`.
// The dispatch of the `minispec` CLI: the arguments in, the exit code and the two streams out.
// It has no `node:` import, so a test runs it with a fake store. `cli.ts` gives the real store and prints the reply.

import { parseArgs } from "../domain/args.ts";
import { COMMANDS, commandHelp, mainHelp } from "../domain/help.ts";
import { colorOn, hintOf, nearest, paint } from "../domain/text.ts";
import { type Context, EXIT, type Reply } from "../domain/types.ts";
import { UNKNOWN_COMMAND } from "../prompts.ts";
import { archiveCommand } from "./archive.ts";
import {
  fail,
  listCommand,
  newCommand,
  showCommand,
  statusCommand,
} from "./commands.ts";
import { validateCommand } from "./validate.ts";

/** What the CLI knows about its streams and its environment. */
export interface Terminal {
  readonly stdout: boolean;
  readonly stderr: boolean;
  readonly noColorEnv: string | undefined;
}

/** Gives the context of a run. It is called after the arguments pass, so help and a usage fault read no file. */
export type MakeContext = () => Promise<Context>;

const dispatch = async (
  command: string,
  words: readonly string[],
  ctx: Context,
  parsed: ReturnType<typeof parseArgs>,
): Promise<Reply> => {
  const { options } = parsed;
  switch (command) {
    case "new":
      return newCommand(ctx, words, options);
    case "list":
      return listCommand(ctx, options);
    case "show":
      return showCommand(ctx, words, options);
    case "status":
      return statusCommand(ctx, words, options);
    case "validate":
      return validateCommand(ctx, words[0], options.json);
    default:
      return archiveCommand(ctx, words, options);
  }
};

/** The reply for `argv`. The messages carry color only when the stream is a terminal, `NO_COLOR` is empty, and `--no-color` is absent. */
export const run = async (
  argv: readonly string[],
  makeContext: MakeContext,
  terminal: Terminal,
): Promise<Reply> => {
  const parsed = parseArgs(argv);
  const { command } = parsed;
  const known = Object.keys(COMMANDS);
  if (parsed.error !== null) return fail(parsed.error, EXIT.usage);
  if (command === null || command === "help")
    return { code: EXIT.ok, out: mainHelp(), err: "" };
  if (!known.includes(command)) {
    const near = nearest(command, known);
    return fail(UNKNOWN_COMMAND({ command, hint: hintOf(near) }), EXIT.usage);
  }
  if (parsed.help) return { code: EXIT.ok, out: commandHelp(command), err: "" };
  const reply = await dispatch(
    command,
    parsed.words,
    await makeContext(),
    parsed,
  );
  if (parsed.options.json) return reply;
  const on = (isTerminal: boolean) =>
    colorOn(isTerminal, terminal.noColorEnv, parsed.noColor);
  return {
    code: reply.code,
    out: on(terminal.stdout)
      ? reply.out.replace(/^Valid:/, paint(true, "green", "Valid:"))
      : reply.out,
    err: reply.err
      ? `${paint(on(terminal.stderr), "red", "error:")} ${reply.err}`
      : "",
  };
};
